def run_plugin(path: str) -> str uses fs:
    """Run `plugin(path)` with `fs` confined to the directory `notes`, so the plugin can read only below it; reads outside yield an empty string. `path` is relative to `notes`."""
    post out.char_count() >= 0
    with fs = fs.sub("notes"):
        return plugin(path)

def plugin(path: str) -> str uses fs:
    mine = fs.read(path) else ""
    theirs = fs.read("notes/../secret.txt") else ""
    return mine + "|" + theirs
